document.addEventListener("DOMContentLoaded",async()=>{await yalcaInitPortalShell()&&(document.getElementById("stockFilter").addEventListener("change",renderEstoque),document.getElementById("stockSearch").addEventListener("input",renderEstoque),renderEstoque())});const STOCK_STATUS_VISUALS={OK:{color:"var(--good)",badge:"badge--ok"},Baixo:{color:"var(--warning)",badge:"badge--baixo"},Esgotado:{color:"var(--critical)",badge:"badge--esgotado"},Parado:{color:"var(--serious)",badge:"badge--parado"}};function renderStockStatusStack(t){const a=document.getElementById("stockStatusStack"),e=document.getElementById("stockStatusLegend"),s=t.length;if(0===s)return a.innerHTML="",void(e.innerHTML='<p class="alert-empty">Nenhum produto cadastrado.</p>');const o={OK:0,Baixo:0,Esgotado:0,Parado:0};t.forEach(t=>{o[t.status_calc]=(o[t.status_calc]||0)+1}),a.innerHTML=Object.entries(o).filter(([,t])=>t>0).map(([t,a])=>{const e=a/s*100;return`<div class="status-stack__seg" style="width:${e}%; background:${STOCK_STATUS_VISUALS[t].color};" title="${t}: ${a} produto(s) (${e.toFixed(1)}%)"></div>`}).join(""),e.innerHTML=Object.entries(o).filter(([,t])=>t>0).map(([t,a])=>`\n    <span class="status-stack__legend-item"><span class="status-stack__legend-swatch" style="background:${STOCK_STATUS_VISUALS[t].color}"></span>${t}: <strong style="color:var(--text);">${a}</strong> (${(a/s*100).toFixed(1)}%)</span>\n  `).join("")}function renderEstoque(){const t=document.getElementById("stockFilter").value||"todos",a=SHELL_DATA.products.map(t=>({...t,status_calc:yalcaStockStatus(t)})),e="todos"===t?a:a.filter(a=>a.status_calc===t),s=a.filter(t=>"Esgotado"===t.status_calc).length,o=a.filter(t=>"Baixo"===t.status_calc).length,n=a.filter(t=>"Parado"===t.status_calc),l=n.reduce((t,a)=>t+a.cost*a.stock,0);renderKpiGrid("stockKpis",[{label:"Esgotados",value:s,delta:null},{label:"Estoque baixo",value:o,delta:null},{label:"Estoque parado",value:n.length,delta:null},{label:"Capital parado em estoque",value:yalcaFormatCurrency(l),delta:null,hint:"custo × unidades de itens parados"}]),renderStockStatusStack(a);const d=[];a.filter(t=>"Esgotado"===t.status_calc).forEach(t=>d.push({level:"critical",icon:"⛔",title:`${t.name} esgotado`,sub:`${t.marketplace} · vendia ${t.unitsSoldMonth}/mês`})),a.filter(t=>"Baixo"===t.status_calc).forEach(t=>d.push({level:"warning",icon:"⚠️",title:`Estoque baixo: ${t.name}`,sub:`${t.stock} unidades restantes (mínimo: ${t.minStock})`})),a.filter(t=>"Parado"===t.status_calc).forEach(t=>d.push({level:"",icon:"🐌",title:`${t.name} está parado`,sub:`${t.stock} unidades em estoque, só ${t.unitsSoldMonth} vendidas no mês — ${yalcaFormatCurrency(t.cost*t.stock)} parados`})),renderAlertList(document.getElementById("stockAlerts"),d.slice(0,8));const c=document.getElementById("stockSearch").value.trim().toLowerCase(),r=c?e.filter(t=>t.sku.toLowerCase().includes(c)||t.name.toLowerCase().includes(c)):e,u=document.getElementById("stockTableBody");if(0===r.length)return void(u.innerHTML=`<tr><td colspan="6" class="alert-empty">${0===e.length?"Nenhum produto nesse status.":"Nenhum produto encontrado para essa busca."}</td></tr>`);const i={OK:"ok",Baixo:"baixo",Esgotado:"esgotado",Parado:"parado"};u.innerHTML=r.map(t=>`\n    <tr>\n      <td data-label="SKU">${yalcaEscapeHtml(t.sku)}</td>\n      <td data-label="Produto">${yalcaEscapeHtml(t.name)}</td>\n      <td class="num" data-label="Estoque">${t.stock}</td>\n      <td class="num" data-label="Mínimo">${t.minStock}</td>\n      <td class="num" data-label="Vendidos/mês">${t.unitsSoldMonth}</td>\n      <td data-label="Status"><span class="badge badge--${i[t.status_calc]}">${t.status_calc}</span></td>\n    </tr>`).join("")}